(() => {
  'use strict';
  const G = window.LifeGame;
  const app = document.querySelector('#app');
  let state = null, selected = 'student', feedback = false, busy = false;
  let collection = [];
  try { const saved = JSON.parse(localStorage.getItem('maimen-endings-v1') || '[]'); if (Array.isArray(saved)) collection = saved.filter(x => Object.hasOwn(G.endings, x)); } catch (_) {}
  const burger = `<svg viewBox="0 0 360 300" aria-hidden="true" class="burger-art"><ellipse cx="180" cy="265" rx="130" ry="17" fill="#541c20" opacity=".12"/><g transform="rotate(-9 180 150)"><path d="M65 131C69 40 291 40 295 131Z" fill="#eda73b" stroke="#612a24" stroke-width="5"/><path d="M80 110C112 49 242 54 272 107" fill="none" stroke="#ffc960" stroke-width="13" stroke-linecap="round"/><g stroke="#fff1c8" stroke-width="7" stroke-linecap="round"><path d="M122 86l7 4m40-17l6 5m42 0l-3 6m31 14l7-2m-98 12l5-4"/></g><path d="M60 145q18-18 38 0t38 0t38 0t38 0t38 0t48 0l-5 25H66Z" fill="#7b9948" stroke="#612a24" stroke-width="5"/><rect x="60" y="170" width="240" height="32" rx="16" fill="#74382b" stroke="#612a24" stroke-width="5"/><path d="M64 163h229l-56 29-62-18-51 22Z" fill="#ffcc45" stroke="#612a24" stroke-width="4"/><path d="M67 209h227q-2 44-47 44H114q-47 0-47-44Z" fill="#e8a044" stroke="#612a24" stroke-width="5"/><path d="M93 231q70 18 174 0" fill="none" stroke="#f8bc61" stroke-width="10" stroke-linecap="round"/></g></svg>`;
  function toast(text) { const el = document.querySelector('#toast'); el.textContent = text; el.classList.add('visible'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('visible'), 2400); }
  function focusHeading() { const h = app.querySelector('h1'); if (h) { h.setAttribute('tabindex', '-1'); h.focus({ preventScroll: true }); } }
  function renderHome() {
    state = null; feedback = false;
    app.innerHTML = `<section class="home-grid"><div class="hero-copy"><div class="eyebrow"><span class="short-line"></span> ORDINARY DAY. EXTRA HAPPINESS.</div><h1>人生大事，<br>先<span class="underlined">吃口快乐。</span></h1><p class="intro">扮演一个平凡的人，过不太平凡的一天。<br>没有标准答案，只有属于你的今日套餐。</p><div class="hero-art">${burger}<span class="art-star star-one">✦</span><span class="art-star star-two">✧</span><div class="round-stamp">快乐不必<br><b>等明天</b></div><span class="art-caption">A LITTLE BITE OF A GOOD LIFE.</span></div><div class="game-facts"><span>◷ 约 3 分钟一局</span><span>↗ 3 种人生结局</span><span>♡ 没有失败选项</span></div></div><section class="ticket select-ticket"><div class="ticket-top"><span>NEW LIFE / 新的一局</span><span>NO. 001</span></div><div class="ticket-body"><span class="eyebrow muted">STEP 01 · 选个身份</span><h2>今天，你是谁？</h2><p class="section-sub">把日常放一边，换个人生试试看。</p><div class="role-list">${G.roles.map(r => `<button class="role-card ${r.id === selected ? 'selected' : ''}" data-role="${r.id}" aria-pressed="${r.id === selected}"><span class="role-emoji">${r.icon}</span><span class="role-info"><small>${r.label} · 初始预算 ¥${r.cash}</small><strong>${r.name}</strong><span>${r.subtitle}</span></span><span class="role-radio" aria-hidden="true"></span></button>`).join('')}</div><button class="primary start-button" id="start">就这个，开局！ <span>↗</span></button><p class="tiny center">每个选择，都会给今天加一点不同的味道。</p></div><div class="ticket-bottom"><span>结局收集 <b>${new Set(collection).size} / 3</b></span><span class="collection-icons">${Object.entries(G.endings).map(([k, e]) => `<span title="${collection.includes(k) ? e.title : '尚未解锁'}" class="${collection.includes(k) ? '' : 'locked'}">${e.icon}</span>`).join('')}</span></div></section></section>`;
    app.querySelectorAll('[data-role]').forEach(el => el.addEventListener('click', () => { selected = el.dataset.role; renderHome(); app.querySelector(`[data-role="${selected}"]`).focus({ preventScroll: true }); }));
    document.querySelector('#start').onclick = () => { state = G.start(selected); renderGame(); focusHeading(); };
  }
  function sidebar() {
    const role = G.roles.find(r => r.id === state.roleId);
    return `<aside class="status-panel"><span class="eyebrow muted">PLAYER STATUS</span><div class="player"><span>${role.icon}</span><div><h2>${role.name}</h2><small>普通的一天 · 主角是你</small></div></div><div class="wallet"><span>今日剩余预算</span><strong><small>¥</small>${state.cash}<small>.00</small></strong></div><div class="stat"><div><span>⚡ 精力</span><b>${state.energy} / 100</b></div><div class="meter"><i style="width:${state.energy}%"></i></div></div><div class="stat mood"><div><span>☺ 心情</span><b>${state.mood} / 100</b></div><div class="meter"><i style="width:${state.mood}%"></i></div></div><div class="mini-note"><span>✳ 今日备忘</span><p>${role.intro}</p></div><button class="text-button" id="restart">↶ 重新选个身份</button><p class="tiny">游戏数值仅用于剧情体验。</p></aside>`;
  }
  function bindRestart() { document.querySelector('#restart').onclick = () => { if (window.confirm('要结束这一局，重新选个身份吗？')) { renderHome(); focusHeading(); } }; }
  function effect(o) { return [o.cash ? `预算 −¥${-o.cash}` : null, o.energy ? `精力 ${o.energy > 0 ? '+' : ''}${o.energy}` : null, o.mood ? `心情 +${o.mood}` : null].filter(Boolean).join(' · '); }
  function renderGame() {
    const current = feedback ? null : G.scene(state);
    const step = feedback ? state.step : state.step + 1;
    const labels = ['故事开始', '街角奇遇', '途中插曲', '抵达快乐'];
    const last = state.history.at(-1);
    app.innerHTML = `<section class="play-layout">${sidebar()}<section class="story-panel"><nav class="progress" aria-label="剧情进度">${labels.map((label, i) => `<span class="${i < step ? 'active' : ''}"><i>${i + 1}</i><span>${label}</span></span>`).join('')}</nav><div class="story-content" key="${step}"><div class="eyebrow muted">CHAPTER 0${step} / 04 <span class="chapter-line"></span> ${labels[step - 1]}</div>${feedback ? `<div class="feedback-emoji">✦</div><h1>生活，回应了你。</h1><p class="story-lead">${last.reply}</p><div class="choice-memory">你选择了：${last.choice}</div><button class="primary continue" id="next">${state.step === 4 ? '坐好了，看看吃什么' : '继续今天的故事'} <span>→</span></button>` : `<h1>${current.title}</h1><p class="story-lead">${current.text}</p><div class="chat-bubble"><small>${current.speaker}</small><p>“${current.message}”</p></div><div class="choose-label">轮到你了，你会怎么选？</div><div class="options">${current.options.map((o, i) => `<button class="option" data-choice="${i}"><span class="option-letter">${String.fromCharCode(65 + i)}</span><span><strong>${o.title}</strong><small>${o.desc}</small><em>${effect(o)}</em></span><span class="option-arrow">↗</span></button>`).join('')}</div>`}</div></section></section>`;
    bindRestart();
    if (feedback) document.querySelector('#next').onclick = () => { feedback = false; state.step === 4 ? renderMeals() : renderGame(); focusHeading(); };
    else app.querySelectorAll('[data-choice]').forEach(el => el.onclick = () => { state = G.choose(state, Number(el.dataset.choice)); feedback = true; renderGame(); focusHeading(); });
  }
  function renderMeals() {
    app.innerHTML = `<section class="play-layout">${sidebar()}<section class="story-panel"><div class="story-content meal-content"><div class="eyebrow muted">THE HAPPY PART / 今日补给</div><h1>这一餐，犒劳今天。</h1><p class="story-lead">你还剩 <b>¥${state.cash}</b>。选一份顺眼的套餐，为今天收个好尾。</p><div class="demo-note">ⓘ 虚构套餐与模拟价格，仅在游戏内消耗预算。</div><div class="meal-grid">${G.meals.map(m => `<button class="meal-card" data-meal="${m.id}" ${state.cash < m.price ? 'disabled' : ''}><span class="meal-emoji">${m.icon}</span><h2>${m.name}</h2><p>${m.items}</p><small>${m.note}</small><span class="meal-effects">精力 +${m.energy} · 心情 +${m.mood}</span><div><strong>¥${m.price}<small>.00</small></strong><span>${state.cash < m.price ? '预算不足' : '就吃这份 ↗'}</span></div></button>`).join('')}</div><p class="tiny">选完即生成结局。没有真实支付，也不会创建订单。</p></div></section></section>`;
    bindRestart();
    app.querySelectorAll('[data-meal]').forEach(el => el.onclick = () => { state = G.dine(state, el.dataset.meal); const e = G.ending(state); collection = [...new Set([...collection, e.key])]; try { localStorage.setItem('maimen-endings-v1', JSON.stringify(collection)); } catch (_) {} renderEnding(); focusHeading(); });
  }
  function renderEnding() {
    const e = G.ending(state), meal = G.meals.find(m => m.id === state.mealId), role = G.roles.find(r => r.id === state.roleId);
    app.innerHTML = `<section class="ending-layout"><div class="ending-copy"><div class="eyebrow"><span class="short-line"></span> TODAY WAS A GOOD DAY.</div><div class="ending-icon">${e.icon}</div><span class="ending-tag">解锁今日人生 · ${role.name}</span><h1>${e.title}</h1><p class="ending-quote">“${e.quote}”</p><p class="intro">${e.description}</p><div class="end-stats"><div><strong>${state.energy}</strong><span>最终精力</span></div><div><strong>${state.mood}</strong><span>最终心情</span></div><div><strong>¥${state.cash}</strong><span>剩余预算</span></div></div><div class="end-actions"><button class="primary" id="again">再过另一种人生 ↗</button><button class="secondary" id="share">复制今日故事</button></div><p class="tiny">已收集 ${collection.length} / 3 个结局 · 多试试不同的选择吧</p></div><section class="ticket receipt"><div class="ticket-top"><span>YOUR DAILY RECEIPT</span><span>☺</span></div><div class="ticket-body"><h2>今日快乐小票</h2><p class="receipt-sub">麦门人生模拟器 / 非官方试玩</p><div class="receipt-divider"></div><div class="receipt-row"><span>今日身份</span><b>${role.name}</b></div><div class="receipt-row"><span>开局预算</span><b>¥${role.cash}.00</b></div><div class="journey">${state.history.map((h, i) => `<div><span>0${i + 1}</span><p>${h.choice}</p><b>${h.cash ? '−¥' + -h.cash : '¥0'}</b></div>`).join('')}</div><div class="receipt-meal"><span>${meal.icon}</span><div><b>${meal.name}</b><small>${meal.items}</small></div><strong>¥${meal.price}</strong></div><div class="receipt-divider"></div><div class="receipt-row total"><span>今日总花费</span><b>¥${role.cash - state.cash}.00</b></div><div class="receipt-row"><span>快乐体验</span><b>无价</b></div><div class="barcode" aria-hidden="true"></div><p class="tiny center">THANK YOU FOR BEING YOU.<br>以上为游戏记录，不是实际订单或消费凭证。</p></div></section></section>`;
    document.querySelector('#again').onclick = () => { renderHome(); focusHeading(); };
    document.querySelector('#share').onclick = async () => {
      if (busy) return; busy = true;
      const text = `🍟 我的麦门人生：${e.title}\n${e.quote}\n\n今天我是${role.name}：\n${state.history.map(h => '· ' + h.choice).join('\n')}\n最后选了${meal.name}，剩余预算 ¥${state.cash}。\n\n麦门人生模拟器 · 非官方试玩，套餐和价格均为模拟。`;
      try { if (!navigator.clipboard) throw new Error('clipboard unavailable'); await navigator.clipboard.writeText(text); toast('今日故事已复制，去分享一点快乐吧。'); }
      catch (_) { document.querySelector('#share-text').value = text; document.querySelector('#share-dialog').showModal(); document.querySelector('#share-text').select(); }
      finally { busy = false; }
    };
  }
  document.querySelector('#close-share').onclick = () => document.querySelector('#share-dialog').close();
  document.querySelector('.brand').onclick = event => { event.preventDefault(); if (!state || state.mealId || window.confirm('要结束这一局，返回首页吗？')) { renderHome(); focusHeading(); } };
  renderHome();
})();
